import{_ as a,o as e,c as s,a4 as n}from"./chunks/framework.DUuHxaiX.js";const i="/smartycards/assets/lti-1_external-tool.Bt3dJTNL.png",r="/smartycards/assets/lti-2_choose-find.BhB45N1p.png",o="/smartycards/assets/lti-3_click-smartycards.keyYClcn.png",l="/smartycards/assets/lti-4_select-deck.DXjMvQrJ.png",c="/smartycards/assets/lti-5_choose-select.CnhjU0A7.png",d="/smartycards/assets/lti-6_embedded-in-canvas.LGRwJU7T.png",g="/smartycards/assets/lti-7_grade-recorded.B8fvbAh9.png",f=JSON.parse('{"title":"Using with Canvas (LTI Integration)","description":"","frontmatter":{},"headers":[],"relativePath":"teaching/lti-assignments-in-canvas.md","filePath":"teaching/lti-assignments-in-canvas.md","lastUpdated":1768929607000}'),m={name:"teaching/lti-assignments-in-canvas.md"};function p(h,t,u,y,_,k){return e(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="using-with-canvas-lti-integration" tabindex="-1">Using with Canvas (LTI Integration) <a class="header-anchor" href="#using-with-canvas-lti-integration" aria-label="Permalink to &quot;Using with Canvas (LTI Integration)&quot;">​</a></h1><p>SmartyCards can be integrated with Canvas using LTI (Learning Tools Interoperability). This allows you to <strong>create assignments</strong> that link directly to SmartyCards decks, with <strong>automatic grade passback</strong> to the Canvas gradebook.</p><h2 id="setting-up-an-assignment-in-canvas" tabindex="-1">Setting Up an Assignment in Canvas <a class="header-anchor" href="#setting-up-an-assignment-in-canvas" aria-label="Permalink to &quot;Setting Up an Assignment in Canvas&quot;">​</a></h2><ol><li><p>In Canvas, create a new <strong>Assignment</strong>. Add your assignment details (name, description, points, etc.).</p></li><li><p>For <strong>Submission Type</strong>, select <strong>External Tool</strong><img src="'+i+'" alt="Select External Tool as submission type"></p></li><li><p>Click <strong>Find</strong> to see a list of available tools: <img src="'+r+`" alt="Select SmartyCards from the list of external tool
s"></p></li><li><p>Choose <strong>SmartyCards</strong> from the list: <img src="`+o+'" alt="Select SmartyCards from the list of external tools"></p></li></ol><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Your Canvas administrator must first add and enable the SmartyCards LTI for your institution. If you don&#39;t see SmartyCards in the External Tool list, contact your Canvas admin or email <a href="mailto:latistecharch@umn.edu" target="_blank" rel="noreferrer">latistecharch@umn.edu</a>.</p></div><ol start="5"><li><p><strong>Choose the deck</strong> you want to assign (or create a new deck), and click <strong>Create Assignment</strong>: <img src="'+l+'" alt="Select or create a deck to assign"></p></li><li><p>Click <strong>Select</strong> to confirm your choice: <img src="'+c+'" alt="Click Select to confirm the deck choice"></p></li><li><p><strong>Save</strong> the assignment</p></li><li><p>Your assignment is now set up. You should see it embedded in the assignment page (or a link to open SmartyCards in a new tab): <img src="'+d+'" alt="Final SmartyCards assignment in Canvas"></p></li><li><p>The assignment column is automatically created in the Gradebook. When a student completes their practice session, students will be awarded 100% for completing the activity: <img src="'+g+'" alt="Grade passback in Canvas gradebook"></p></li></ol><h3 id="student-experience" tabindex="-1">Student Experience <a class="header-anchor" href="#student-experience" aria-label="Permalink to &quot;Student Experience&quot;">​</a></h3><p>When students click the assignment:</p><ol><li>They are taken directly to the SmartyCards practice activity</li><li>They practice all cards in the deck</li><li>Once complete, their grade (100%) is automatically submitted to Canvas</li></ol><p>Students can return to the assignment to practice again, but their grade is recorded on first completion.</p><p>Students may also access the practice deck directly in SmartyCards,</p><h3 id="how-grading-works" tabindex="-1">How Grading Works <a class="header-anchor" href="#how-grading-works" aria-label="Permalink to &quot;How Grading Works&quot;">​</a></h3><p>SmartyCards assignments are graded on <strong>participation, not correctness</strong>. Students earn 100% once they complete the practice session by going through all cards in the deck. The goal is to encourage practice and engagement, not to penalize students for getting answers wrong while learning.</p><p>If you have a large deck, consider breaking it into smaller decks for multiple assignments to make it more manageable for students.</p>',14)])])}const v=a(m,[["render",p]]);export{f as __pageData,v as default};
